// Development-only: render the catalog banner and gallery.
//
// The look joins the two projects this plugin connects. Honcho supplies the
// frame: a charcoal canvas with a faint grid, window chrome with double rules
// and bracketed titles, pixel-block clusters, right-angle connectors and a CLI
// box. Nous supplies the content: a Nous-blue strip, original generated art
// (the Nous girl and esoteric geometry) dithered into Nous blue, Neuebit
// headlines, Mondwest mottos and four-point sparkles. The UI is the plugin's
// dark theme with synthetic data.
//
// Art is generated by Hermes's bundled `openai-codex` image provider
// (gpt-image-2). The character prompts used the MIT-licensed Nous Girl mark
// from hermes-agent as a reference image. Prompts, provenance and the MIT
// notice are in docs/catalog/art. Every image says it is an unofficial
// community plugin, and nothing implies affiliation with Nous Research or
// Plastic Labs. Fonts load from the prepared Hermes checkout's
// @nous-research/ui package (MIT) at render time and are not copied.
//
//   HERMES_SOURCE=/path/to/hermes-agent node scripts/catalog-art.mjs
//
// Optional: CATALOG_ART_OUTPUT (default docs/catalog), CATALOG_ART_SOURCES
// (default docs/catalog/art), CATALOG_ART_ONLY=banner.png,gallery-ask.png
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createRequire } from 'node:module'
import { mkdir, readdir, readFile } from 'node:fs/promises'
import { dirname, extname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..')
assert(process.env.HERMES_SOURCE, 'Set HERMES_SOURCE to a prepared Hermes checkout.')
const host = resolve(process.env.HERMES_SOURCE)
const { chromium } = createRequire(join(host, 'package.json'))('playwright')
const fonts = join(host, 'node_modules/@nous-research/ui/dist/fonts')
const assets = join(host, 'apps/desktop/dist/assets')
const shots = join(repo, 'docs/screenshots')
const sources = resolve(process.env.CATALOG_ART_SOURCES || join(repo, 'docs/catalog/art'))
const output = resolve(process.env.CATALOG_ART_OUTPUT || join(repo, 'docs/catalog'))
const only = process.env.CATALOG_ART_ONLY ? new Set(process.env.CATALOG_ART_ONLY.split(',')) : null
await mkdir(output, { recursive: true })
const mono = (await readdir(assets)).find(name => /^JetBrainsMono-Regular-.*\.woff2$/.test(name))
assert(mono, 'Build Hermes Desktop first: JetBrains Mono not found in apps/desktop/dist/assets.')
const sourceFiles = Object.fromEntries((await readdir(sources)).filter(name => /\.(jpe?g|png)$/i.test(name)).map(name => [name.replace(/\.[^.]+$/, ''), name]))

// Nous
const BLUE = '#0000f2'
const PAPER = '#f2f2f2'
const PALE = '#8a8aff'
// Honcho
const CHARCOAL = '#1a1a1a'
const INK = '#e3e3e3'
const MUTED = '#8f8f8f'
const RULE = '#6b6b6b'
const SKY = '#b8d4f2'
const MINT = '#a8f0d8'
const BLOCK = '#2b3440'
// The screenshot harness adds a 38px "synthetic demo data" bar to every capture.
const BAR = 38

// ── Ornaments ───────────────────────────────────────────────────────────────

// An original memory sigil: a heptagram with every chord, tick rings and nodes.
function sigil(size, { ink = INK, field = CHARCOAL, points = 7, ticks = true, weight = 1 } = {}) {
  const c = size / 2
  const outer = c - weight
  const ring = outer * 0.72
  const node = Math.max(2.5, outer * 0.07)
  const f = n => n.toFixed(2)
  const angle = i => -Math.PI / 2 + (i * 2 * Math.PI) / points
  const at = (r, i) => [c + r * Math.cos(angle(i)), c + r * Math.sin(angle(i))]
  const chords = []
  for (let i = 0; i < points; i++) {
    for (let j = i + 1; j < points; j++) {
      const [x1, y1] = at(ring, i)
      const [x2, y2] = at(ring, j)
      chords.push(`<line x1="${f(x1)}" y1="${f(y1)}" x2="${f(x2)}" y2="${f(y2)}"/>`)
    }
  }
  const tickMarks = ticks
    ? Array.from({ length: 72 }, (_, i) => {
        const a = (i * Math.PI * 2) / 72
        const inner = outer * (i % 6 === 0 ? 0.86 : 0.92)
        return `<line x1="${f(c + inner * Math.cos(a))}" y1="${f(c + inner * Math.sin(a))}" x2="${f(c + outer * 0.97 * Math.cos(a))}" y2="${f(c + outer * 0.97 * Math.sin(a))}"/>`
      }).join('')
    : ''
  const nodes = Array.from({ length: points }, (_, i) => {
    const [x, y] = at(ring, i)
    return `<circle cx="${f(x)}" cy="${f(y)}" r="${f(node)}"/>`
  }).join('')
  return `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" style="display:block;overflow:visible">
    <g fill="none" stroke="${ink}" stroke-width="${weight}">
      <circle cx="${c}" cy="${c}" r="${f(outer)}"/>${ticks ? `<circle cx="${c}" cy="${c}" r="${f(outer * 0.84)}"/>` : ''}
      <g stroke-width="${weight * 0.7}" opacity="0.85">${chords.join('')}${tickMarks}</g>
    </g>
    <g fill="${field}" stroke="${ink}" stroke-width="${weight}">${nodes}<circle cx="${c}" cy="${c}" r="${f(node * 1.3)}"/></g>
  </svg>`
}

function spark(x, y, size, color = PAPER) {
  return `<svg class="spark" viewBox="-10 -10 20 20" style="left:${x - size / 2}px;top:${y - size / 2}px;width:${size}px;height:${size}px"><path fill="${color}" d="M0,-10 C0.9,-0.9 0.9,-0.9 10,0 C0.9,0.9 0.9,0.9 0,10 C-0.9,0.9 -0.9,0.9 -10,0 C-0.9,-0.9 -0.9,-0.9 0,-10Z"/></svg>`
}

// Honcho's pixel-block clusters. `cells` are [col, row] on a 25px grid.
function blocks(x, y, cells, color = BLOCK, size = 18) {
  return cells.map(([cx, cy]) => `<div class="block" style="left:${x + cx * 25}px;top:${y + cy * 25}px;width:${size}px;height:${size}px;background:${color}"></div>`).join('')
}

// A right-angle connector: points are [x, y] in page coordinates.
function connector(points, color = RULE) {
  return `<svg class="wire" width="1200" height="600"><polyline fill="none" stroke="${color}" stroke-width="1" points="${points.map(p => p.join(',')).join(' ')}"/></svg>`
}

// A Honcho window: double rules either side of a bracketed title, then a close mark.
function win({ x, y, w, h, title, body, z = 3 }) {
  return `<div class="win" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px;z-index:${z}">
    <div class="bar"><span class="rules"></span><span class="title">[${title}]</span><span class="rules"></span><span class="close">×</span></div>
    <div class="body">${body}</div>
  </div>`
}

// Generated ink art, dithered into Nous blue on paper: ink becomes blue, mid
// tones pale-blue dots. `focus` (a point in the source) lands at `at` in the
// canvas; `zoom` is the share of the source width shown across it. `glitch`
// adds that many corrupted scanlines.
function art({ key, focus = [0.5, 0.5], at = [0.5, 0.5], zoom = 1, gamma = 1, cell = 2, glitch = 0 }) {
  assert(sourceFiles[key], `Missing generated art: ${key}`)
  return `<canvas data-art="/src/${encodeURIComponent(sourceFiles[key])}" data-focus="${focus}" data-at="${at}" data-zoom="${zoom}" data-gamma="${gamma}" data-cell="${cell}" data-glitch="${glitch}"></canvas>`
}

// A screenshot region: source CSS pixels [x, y, width] from a capture that is
// `source` CSS pixels wide, scaled to fill the window body.
function shot({ file, crop = [0, 0, 1200], source = 1200, width }) {
  const [x, y, w] = crop
  const scale = width / w
  return `<img class="shot" src="/shots/${file}" style="width:${source * scale}px;margin-left:${-x * scale}px;margin-top:${-(BAR + y) * scale}px">`
}

function strip(left, right = 'SYNTHETIC DEMO DATA') {
  return `<div class="strip"><span>${left}</span><span>UNOFFICIAL COMMUNITY PLUGIN</span><span>${right}</span></div>`
}

const foot = `<div class="foot">${sigil(40, { ink: SKY, ticks: false })}<div><div class="pixel">HONCHO MEMORY</div><div class="pixel dim">FOR HERMES AGENT</div></div></div>`

// ── Gallery plates ──────────────────────────────────────────────────────────

const ART = { x: 436, y: 62, w: 372, h: 498 }
const UI = { x: 712, y: 196, w: 456, h: 330 }

function plate({ number, section, headline, motto, body, artwork, figure, ui, extra = '', box = ART }) {
  const panes = Array.isArray(ui) ? ui : null
  const ART = box
  return `<div class="grid"></div>${strip(`PL. ${number} · ${section.toUpperCase()}`)}
  <div class="col">
    <div class="pixel sky">${section.toUpperCase()}</div>
    <div class="headline" data-fit="352">${headline.join('<br>')}</div>
    <div class="motto">${motto}</div>
    <p class="body">${body}</p>
    <div style="flex:1"></div>
    ${foot}
  </div>
  ${win({ ...ART, title: `FIG. ${number} · ${figure}`, body: art(artwork) })}
  ${panes
    ? panes.map((pane, i) => win({ x: ART.x + ART.w + 22 + i * 196, y: 80 + i * 30, w: 184, h: 470, title: pane.title, z: 4 + i, body: shot({ ...pane, source: 380, width: 182 }) })).join('')
    : win({ ...UI, title: ui.title, z: 4, body: shot({ ...ui, width: UI.w - 2 }) })}
  ${connector([[ART.x + ART.w / 2, ART.y + ART.h], [ART.x + ART.w / 2, 584], [1040, 584], [1040, panes ? 586 : UI.y + UI.h]])}
  ${blocks(1072, 52, [[0, 0], [1, 0], [1, 1], [2, 1], [3, 1], [2, 2]])}
  ${blocks(400, 520, [[0, 0], [0, 1], [1, 1]], BLUE)}
  ${extra}`
}

