// ── Banners ─────────────────────────────────────────────────────────────────

const MOTTO = 'Memoria quae ratiocinatur.'
const CLI = `<div class="cli"><span class="cli-k">HERMES CLI</span><span class="cli-p">you@hermes ~ %</span><span>hermes plugins install hermes-honcho-plugin</span><span class="cursor"></span></div>`
const HERO = { key: 'hero', focus: [0.56, 0.44], at: [0.5, 0.44], zoom: 0.96, glitch: 7 }

